'use strict';

/**
 * DEPLOYMENT-SUPPLIED BEDROCK CONFIGURATION — guardrail and inference profile.
 *
 * These are facts about a particular AWS account, not facts about this
 * software. The guardrail id is generated by AWS when the guardrail is
 * created; the inference profile depends on which profiles the account has
 * access to. Neither can be known from source, and neither has been verified
 * from a developer machine — the resources were created through the AWS
 * console by the owner, who is the only person who can read their identifiers.
 *
 * So the code refuses to invent them. Every value below is read from the
 * environment and validated for SHAPE only; anything absent or malformed
 * disables Bedrock rather than producing a call with a plausible-looking guess.
 *
 * WHY ABSENT MUST MEAN DISABLED, NOT UNGUARDED
 * ────────────────────────────────────────────
 * A Bedrock call with no guardrail header succeeds. It returns a normal, well
 * formed, entirely usable clinical draft. Nothing in the response says the
 * safety layer was skipped, the audit row looks identical, and the therapist
 * sees the same screen. The failure is silent and total, and it would persist
 * for as long as nobody thought to check.
 *
 * A missing guardrail is therefore treated exactly like a thrown kill switch:
 * generation stops, the phone is told 'unavailable', and the therapist writes
 * the note themselves. Losing the feature for an afternoon is recoverable.
 * Clinical content processed without the control the practice believes is
 * there is not.
 */

/**
 * Guardrail identifiers are AWS-generated: lowercase alphanumeric, or a full
 * ARN. Validated for shape only — whether the id EXISTS can be established by
 * exactly one thing, which is AWS answering a call with it.
 */
const GUARDRAIL_ID_PATTERN = /^([a-z0-9]{4,64}|arn:aws:bedrock:[a-z0-9-]+:\d{12}:guardrail\/[a-zA-Z0-9-]+)$/;

/** A numeric version, or the literal DRAFT that AWS uses for the unpublished one. */
const GUARDRAIL_VERSION_PATTERN = /^(\d{1,10}|DRAFT)$/;

const read = (key) => {
  const raw = process.env[key];
  return typeof raw === 'string' && raw.trim() ? raw.trim() : null;
};

/**
 * Resolve the guardrail to apply to every clinical Bedrock call.
 *
 * @returns {{ok: true, id: string, version: string}
 *          |{ok: false, reason: string, configured: boolean}}
 *          `configured: false` means nothing was supplied at all — the normal
 *          state in development and test, where the mock provider is used and
 *          no guardrail exists. `configured: true` with ok:false is a genuine
 *          misconfiguration and is reported far more loudly.
 */
function resolveGuardrail() {
  const id = read('BEDROCK_GUARDRAIL_ID');
  const version = read('BEDROCK_GUARDRAIL_VERSION');

  if (!id && !version) {
    return { ok: false, reason: 'guardrail_not_configured', configured: false };
  }
  // Half-configured is the dangerous state: someone was mid-way through
  // setting this up. It must never resolve to "close enough".
  if (!id) return { ok: false, reason: 'guardrail_id_missing', configured: true };
  if (!version) return { ok: false, reason: 'guardrail_version_missing', configured: true };

  // Reasons carry the failing RULE, never the value. This string reaches the
  // health endpoint, and an identifier there would be an unnecessary
  // disclosure of the account's internals.
  if (!GUARDRAIL_ID_PATTERN.test(id)) {
    return { ok: false, reason: 'guardrail_id_malformed', configured: true };
  }
  if (!GUARDRAIL_VERSION_PATTERN.test(version)) {
    return { ok: false, reason: 'guardrail_version_malformed', configured: true };
  }
  // DRAFT is the unpublished, mutable version. It is fine while an operator is
  // tuning the guardrail and wrong for anything a therapist will rely on,
  // because its behaviour can change under the running application without a
  // deployment. Permitted, and surfaced.
  return { ok: true, id, version, isDraft: version === 'DRAFT' };
}

/**
 * Deployment override for the clinical inference profile.
 *
 * The registry stays the only place a model id may be WRITTEN; this lets a
 * deployment choose which approved profile to use without a code change, which
 * matters because profile availability differs per AWS account and this one
 * cannot be inspected from here.
 *
 * The override is validated against the same invariants as a registry entry:
 * it must be an Australian geo profile and must not be a Covered Model. An
 * override that fails either is refused outright rather than downgraded to the
 * default, because silently ignoring an operator's explicit instruction and
 * calling a different model is worse than not starting.
 *
 * @param {object} registry injected to keep this module free of model strings
 * @returns {{ok: true, id: string|null}|{ok: false, reason: string}}
 *          `id: null` means no override — use the registry default.
 */
function resolveModelProfileOverride(registry) {
  const id = read('BEDROCK_MODEL_ID');
  if (!id) return { ok: true, id: null };

  if (!id.startsWith(registry.AU_GEO_PREFIX)) {
    return { ok: false, reason: 'model_profile_not_au_geo' };
  }
  if (registry.PERMANENTLY_BLOCKED[id]) {
    return { ok: false, reason: 'model_profile_permanently_blocked' };
  }
  // case_note_drafts.model_id is VARCHAR(80). A longer value would be accepted
  // here, invoked successfully, and then fail on INSERT — after the clinical
  // content had already been sent. Refusing up front keeps the failure before
  // transmission rather than after it.
  if (id.length > 80) return { ok: false, reason: 'model_profile_too_long' };
  return { ok: true, id };
}

/**
 * A redacted view for the health endpoint and the boot log.
 *
 * Reports whether each input resolved, never what it resolved to. An operator
 * needs to know the guardrail is pinned and at which version; nobody reading a
 * status page needs its identifier.
 */
function describe(registry) {
  const guardrail = resolveGuardrail();
  const profile = resolveModelProfileOverride(registry);
  return {
    guardrail: guardrail.ok
      ? { configured: true, version: guardrail.version, isDraft: !!guardrail.isDraft }
      : { configured: !!guardrail.configured, reason: guardrail.reason },
    modelProfileOverride: profile.ok
      ? { configured: profile.id !== null }
      : { configured: true, reason: profile.reason },
  };
}

module.exports = {
  resolveGuardrail,
  resolveModelProfileOverride,
  describe,
  GUARDRAIL_ID_PATTERN,
  GUARDRAIL_VERSION_PATTERN,
};
